interface JourneyProbeBridge {
  snapshot: () => Record<string, unknown>;
  getSnapshot: () => Record<string, unknown>;
  clearInteractionTrace: () => void;
  prepareScenario: (scenarioId: string) => JourneyProbePreparationRecord;
  releaseScenario: (scenarioId?: string) => void;
}

declare global {
  interface Window {
    __paravoxiaJourneyProbe?: JourneyProbeBridge;
  }
}

function probeEnabled(): boolean {
  if (typeof window === 'undefined') return false;
  const params = new URLSearchParams(window.location.search);
  return params.get('journeyprobe') === '1' || params.get('chapterjourney') === '1';
}

const PREPARATION_BEATS: Readonly<Record<string, string>> = Object.freeze({
  'input:voyage-worker-name': 'voyage',
  'interaction:persistent-scar-arbitration': 'ch7-reconstruct'
});

function deniedPreparation(
  scenarioId: string,
  storyBeat: string | null,
  reason: string
): JourneyProbePreparationRecord {
  return recordJourneyProbePreparation(scenarioId, storyBeat, {
    status: 'denied',
    handlerId: 'journey-runtime-probe-bridge',
    reason
  });
}

/**
 * Direct-entry assistance is deliberately narrower than the read-only probe:
 * the caller must identify the exact scenario and noncertifying lane in the
 * URL, and the live story beat must agree. Ordinary play and continuous proof
 * therefore cannot acquire reconstructed prerequisites through this seam.
 */
function preparationIdentityReason(scenarioId: string, storyBeat: string | null): string | null {
  if (typeof window === 'undefined') return 'browser-window-unavailable';
  const expectedBeat = PREPARATION_BEATS[scenarioId];
  if (!expectedBeat) return 'scenario-not-whitelisted';
  const params = new URLSearchParams(window.location.search);
  if (params.get('journeyprobe') !== '1' && params.get('chapterjourney') !== '1') {
    return 'journey-probe-query-missing';
  }
  if (params.get('debug') !== '1') return 'debug-query-missing';
  if (params.get('journeylane') !== 'direct-entry') return 'lane-is-not-direct-entry';
  if (params.get('journeyscenario') !== scenarioId) return 'scenario-query-mismatch';
  if (params.get('story') !== expectedBeat) return 'story-query-mismatch';
  if (storyBeat !== expectedBeat) return 'live-story-beat-mismatch';
  return null;
}

function elementSnapshot(element: Element | null): Record<string, unknown> | null {
  if (!(element instanceof HTMLElement)) return null;
  const editable = element instanceof HTMLInputElement
    || element instanceof HTMLTextAreaElement
    || element.isContentEditable;
  return {
    tag: element.tagName.toLowerCase(),
    id: element.id || null,
    name: element.getAttribute('name'),
    type: element instanceof HTMLInputElement ? element.type : null,
    editable,
    voyageWorkerNameInput: element.dataset.voyageWorkerNameInput === 'true',
    value: element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement
      ? element.value
      : null
  };
}

function visiblePromptSnapshots(): Record<string, unknown>[] {
  return [...document.querySelectorAll<HTMLElement>('[data-interaction-prompt="primary"]')]
    .filter(element => {
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.display !== 'none'
        && style.visibility !== 'hidden'
        && Number(style.opacity) > 0
        && rect.width > 0
        && rect.height > 0;
    })
    .map(element => {
      const rect = element.getBoundingClientRect();
      return {
        id: element.dataset.interactionId ?? null,
        owner: element.dataset.interactionOwner ?? null,
        scope: element.dataset.interactionScope ?? null,
        rect: {
          left: rect.left,
          top: rect.top,
          right: rect.right,
          bottom: rect.bottom,
          width: rect.width,
          height: rect.height
        }
      };
    });
}

function buildSnapshot(): Record<string, unknown> {
  const story = getStoryStateSnapshot();
  const objective = getActiveGuidedStoryObjective();
  const entityRuntime = getJourneyEntitySnapshot();
  const resolution = getStoryInteractionResolutionSnapshot();
  const trace = getStoryInteractionTrace();
  const prompts = visiblePromptSnapshots();
  const input = getJourneyInputSnapshot();
  const workerName = getWorkerName();
  const localActorId = getLocalActorId();
  const progression = getProgressionSnapshot();
  const localProgression = progression[localActorId] ?? null;
  const spaceFlight = getSpaceFlightSnapshot();
  const systemFlight = getSystemFlightSnapshot();
  const shipRestoration = getShipRestorationSnapshot();
  const signedSceneAv = getSignedSceneAvDebugSnapshot();
  return {
    schema: 'paravoxia.journeyRuntimeSnapshot.v1',
    unfinishedMap: getUnfinishedMapSnapshot(),
    sampledAt: Date.now(),
    story: {
      active: story.active,
      chapter: story.chapter,
      beat: story.beat,
      runId: story.runId
    },
    objective: objective ? {
      ...objective,
      workOrder: [...objective.workOrder],
      health: getGuidedStoryObjectiveHealth(),
      revision: getGuidedStoryObjectiveVersion()
    } : {
      id: null,
      health: getGuidedStoryObjectiveHealth(),
      revision: getGuidedStoryObjectiveVersion()
    },
    interaction: {
      ...resolution,
      published: getInteractionProbeSnapshot(),
      trace,
      effects: trace.entries,
      prompts,
      visiblePromptCount: prompts.length
    },
    entities: entityRuntime.entities,
    entityEvents: entityRuntime.events,
    entityRevision: entityRuntime.revision,
    receipts: progression,
    state: {
      localActor: {
        id: localActorId,
        era: localProgression?.era ?? null,
        milestones: [...(localProgression?.milestones ?? [])]
      },
      spaceFlight: {
        ...spaceFlight,
        destination: spaceFlight.destination ? { ...spaceFlight.destination } : null,
        target: spaceFlight.target ? { ...spaceFlight.target } : null
      },
      systemFlight: {
        ...systemFlight,
        pose: {
          position: [...systemFlight.pose.position],
          velocity: [...systemFlight.pose.velocity],
          quaternion: [...systemFlight.pose.quaternion]
        },
        // Deep-copied per kind. An spaceStation target carries an address like a
        // planet does but is not one, so the old "planet or else a coordinate"
        // split would have handed the probe an undefined coordinate.
        target: systemFlight.target
          ? systemFlight.target.kind === 'star_system'
            ? {
              ...systemFlight.target,
              coordinate: { ...systemFlight.target.coordinate }
            }
            : {
              ...systemFlight.target,
              address: {
                ...systemFlight.target.address,
                system: { ...systemFlight.target.address.system }
              }
            }
          : null,
        renderOrigin: [...systemFlight.renderOrigin]
      },
      shipRestoration: {
        ...shipRestoration,
        parkedPose: shipRestoration.parkedPose ? {
          position: [...shipRestoration.parkedPose.position],
          quaternion: [...shipRestoration.parkedPose.quaternion]
        } : null,
        systemPose: shipRestoration.systemPose ? {
          position: [...shipRestoration.systemPose.position],
          velocity: [...shipRestoration.systemPose.velocity],
          quaternion: [...shipRestoration.systemPose.quaternion]
        } : null,
        repairHistory: shipRestoration.repairHistory.map(commit => ({ ...commit }))
      },
      signedSceneAv: {
        active: signedSceneAv.active,
        suspended: signedSceneAv.suspended,
        beat: signedSceneAv.beat,
        anchorId: signedSceneAv.anchorId,
        anchorEvent: signedSceneAv.anchorEvent,
        activationSequence: signedSceneAv.activationSequence,
        activationHistoryAnchorIds: [...signedSceneAv.activationHistoryAnchorIds]
      },
      voyage: {
        'worker-name': workerName
      }
    },
    input: {
      ...input,
      workerName,
      activeElement: elementSnapshot(document.activeElement)
    },
    preparation: getJourneyProbePreparationSnapshot()
  };
}

/**
 * Query-gated bridge for real-browser journey evidence. Snapshot reads are
 * passive. Its two whitelisted direct-entry preparations are separately gated,
 * explicitly receipted, and noncertifying; ordinary play mounts no visible
 * harness and cannot invoke them.
 */
const JourneyRuntimeProbeBridge: React.FC = () => {
  useEffect(() => {
    if (!probeEnabled()) return undefined;
    let diagnosticGazeOwned = false;
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target;
      const targetEditable = target instanceof HTMLInputElement
        || target instanceof HTMLTextAreaElement
        || target instanceof HTMLElement && target.isContentEditable;
      recordJourneyGameplayHotkeyBoundary(event.code, targetEditable);
    };
    const releaseScenario = (scenarioId?: string) => {
      if (!diagnosticGazeOwned
        || scenarioId && scenarioId !== 'interaction:persistent-scar-arbitration') return;
      setCinematicLookWeight(0);
      setCinematicLookTarget(null);
      setCinematicGazeIntent(null);
      diagnosticGazeOwned = false;
    };
    const prepareScenario = (scenarioId: string): JourneyProbePreparationRecord => {
      const story = getStoryStateSnapshot();
      const reason = preparationIdentityReason(scenarioId, story.beat);
      if (reason) return deniedPreparation(scenarioId, story.beat, reason);

      if (scenarioId === 'input:voyage-worker-name') {
        return requestJourneyProbePreparation(scenarioId, story.beat);
      }

      const target = hifiWreckHandle.diagnosisTarget;
      if (!target || !hifiWreckHandle.converted) {
        return recordJourneyProbePreparation(scenarioId, story.beat, {
          status: 'waiting',
          handlerId: 'wreck-diagnostic-gaze',
          reason: 'wreck-diagnosis-target-not-ready'
        });
      }
      const player = getPlayerWorldPosition();
      setCinematicGazeIntent(null);
      setCinematicLookTarget(target);
      setCinematicLookWeight(1);
      diagnosticGazeOwned = true;
      return recordJourneyProbePreparation(scenarioId, story.beat, {
        status: 'prepared',
        handlerId: 'wreck-diagnostic-gaze',
        evidence: {
          assistance: 'gaze-only',
          movedPlayer: false,
          playerPosition: player.toArray(),
          targetPosition: target.toArray(),
          distance: Math.round(player.distanceTo(target) * 1000) / 1000
        }
      });
    };
    const bridge: JourneyProbeBridge = {
      snapshot: buildSnapshot,
      getSnapshot: buildSnapshot,
      clearInteractionTrace: clearStoryInteractionTrace,
      prepareScenario,
      releaseScenario
    };
    window.__paravoxiaJourneyProbe = bridge;
    window.addEventListener('keydown', onKeyDown);
    return () => {
      releaseScenario();
      window.removeEventListener('keydown', onKeyDown);
      if (window.__paravoxiaJourneyProbe === bridge) {
        delete window.__paravoxiaJourneyProbe;
      }
    };
  }, []);
  return null;
};

export default JourneyRuntimeProbeBridge;

// --- Common Ground (ch13) route and reference geometry ------------------------------
//
// PURE over injected terrain queries. Nothing here imports THREE, React, the
// voxel system or the world; the caller supplies "is this footing real" and this
// module answers "is that span demonstrable, and if not, literally why".
//
// The refusal reasons are the whole point of the chapter. "It didn't work" is
// not an answer a surveyor accepts, so every hold names the physical cause and
// each cause has a different, reachable repair:
//
//   reference-out-of-range              -> stand closer, or occupy the witness
//   reference-occluded-survey-housing   -> the apparatus's own backing is in the
//                                          way; occupy the witness or go around
//   reference-occluded-other-solid      -> some other solid (the hero tree's
//                                          trunk collider) is in the way
//   footing-invalid                     -> revise the path; NO witness repairs it
//
// The last line is a rule, not a nicety: an unsafe step is unsafe whoever is
// watching it, so occupancy must never launder it.

import {
  BODY_BODY_CLEARANCE_UNITS,
  FIXED_REFERENCE_SOCKET_HEIGHT,
  OCCUPANCY_RADIUS_UNITS,
  OCCUPANCY_VERTICAL_UNITS,
  PLAYER_REFERENCE_SOCKET_HEIGHT,
  REFERENCE_RANGE_UNITS,
  RELEASE_RADIUS_UNITS,
  RELEASE_VERTICAL_UNITS,
  WORKER_REFERENCE_SOCKET_HEIGHT,
  distanceBetween,
  type CommonGroundHoldReason,
  type CommonGroundPoint
} from './commonGroundState.ts';

export interface CommonGroundAabb {
  readonly name: string;
  readonly lo: CommonGroundPoint;
  readonly hi: CommonGroundPoint;
}

/**
 * The survey apparatus's collision solids, exactly as qualified.
 *
 * backing -> bracket -> stand -> cap is ONE contiguous chain from the dry ground
 * column to the fixed reference plane, and the socket at (-34, 52.35, 20) lies
 * exactly on the cap's top face. There is no floating head, and there is no
 * exemption: all four boxes are in the walk mask, the walked-segment test and
 * every reference ray.
 */
export const CG_APPARATUS_SOLIDS: readonly CommonGroundAabb[] = Object.freeze([
  Object.freeze({
    name: 'backing',
    lo: Object.freeze({ x: -34.8, y: 51.35, z: 19.04 }),
    hi: Object.freeze({ x: -33.2, y: 53.35, z: 19.16 })
  }),
  Object.freeze({
    name: 'stand',
    lo: Object.freeze({ x: -34.2, y: 51.05, z: 19.8 }),
    hi: Object.freeze({ x: -33.8, y: 52.25, z: 20.2 })
  }),
  Object.freeze({
    name: 'bracket',
    lo: Object.freeze({ x: -34.2, y: 51.85, z: 19.04 }),
    hi: Object.freeze({ x: -33.8, y: 52.25, z: 19.9 })
  }),
  Object.freeze({
    name: 'cap',
    lo: Object.freeze({ x: -34.2, y: 52.25, z: 19.8 }),
    hi: Object.freeze({ x: -33.8, y: 52.35, z: 20.2 })
  })
]);

/**
 * The apparatus's fixed reference socket: base + 1.30, lying exactly ON the
 * cap's top face at (-34, 52.35, 20).
 *
 * WRITTEN AS THE QUALIFIED LITERAL, NOT AS `51.05 + 1.3`. In binary that sum is
 * 52.349999999999994 — six femtometres BELOW the cap's top plane, which puts the
 * socket inside its own housing and makes every reference ray an interior
 * crossing. The instrument then occludes itself from everywhere and no route can
 * ever be demonstrated. The contact rule is deliberately epsilon-free (a
 * 0.12-thick slab must still block), so the fix belongs here, in the coordinate,
 * exactly as the qualification states it.
 */
export const CG_FIXED_SOCKET: CommonGroundPoint = Object.freeze({ x: -34, y: 52.35, z: 20 });

/** The nominal socket height the literal above realizes; asserted by the tests. */
export const CG_FIXED_SOCKET_NOMINAL_HEIGHT = FIXED_REFERENCE_SOCKET_HEIGHT;

export function workerSocket(pose: CommonGroundPoint): CommonGroundPoint {
  return { x: pose.x, y: pose.y + WORKER_REFERENCE_SOCKET_HEIGHT, z: pose.z };
}

export function playerSocket(pose: CommonGroundPoint): CommonGroundPoint {
  return { x: pose.x, y: pose.y + PLAYER_REFERENCE_SOCKET_HEIGHT, z: pose.z };
}

// --- Segment/box predicates ----------------------------------------------------------

/**
 * Inclusive slab test. Used by the WALK mask, the walked-segment test and the
 * body capsule, where touching a solid is contact and contact stops you.
 */
export function segmentHitsBoxInclusive(
  a: CommonGroundPoint,
  b: CommonGroundPoint,
  box: CommonGroundAabb
): boolean {
  let near = 0;
  let far = 1;
  const axes: readonly ['x' | 'y' | 'z', number, number][] = [
    ['x', box.lo.x, box.hi.x],
    ['y', box.lo.y, box.hi.y],
    ['z', box.lo.z, box.hi.z]
  ];
  for (const [axis, lo, hi] of axes) {
    const start = a[axis];
    const delta = b[axis] - start;
    if (delta === 0) {
      if (start < lo || start > hi) return false;
      continue;
    }
    const t0 = (lo - start) / delta;
    const t1 = (hi - start) / delta;
    near = Math.max(near, Math.min(t0, t1));
    far = Math.min(far, Math.max(t0, t1));
    if (near > far) return false;
  }
  return true;
}

/**
 * Reference-ray rule: endpoint-only contact is harmless iff the adjacent OPEN
 * segment stays outside the solid; any interior crossing blocks.
 *
 * Applied symmetrically at both endpoints, to every box, with NO object-specific
 * exemption — the apparatus does not get to be transparent to its own instrument
 * just because it owns it. Exact parametric arithmetic, no spatial epsilon, so a
 * 0.12-thick backing slab still blocks. A segment lying IN a face plane produces
 * a positive-length open interval from the other two slabs and therefore blocks;
 * that is deliberate and conservative.
 */
export function referenceSegmentBlockedBy(
  a: CommonGroundPoint,
  b: CommonGroundPoint,
  box: CommonGroundAabb
): boolean {
  let near = 0;
  let far = 1;
  const axes: readonly ['x' | 'y' | 'z', number, number][] = [
    ['x', box.lo.x, box.hi.x],
    ['y', box.lo.y, box.hi.y],
    ['z', box.lo.z, box.hi.z]
  ];
  for (const [axis, lo, hi] of axes) {
    const start = a[axis];
    const delta = b[axis] - start;
    if (delta === 0) {
      if (start < lo || start > hi) return false;
      continue;
    }
    const t0 = (lo - start) / delta;
    const t1 = (hi - start) / delta;
    near = Math.max(near, Math.min(t0, t1));
    far = Math.min(far, Math.max(t0, t1));
    if (near > far) return false;
  }
  // The overlap is a single touch point at an endpoint (or a tangent corner):
  // the open segment never enters the solid.
  return far > near;
}

export interface ReferenceCheckOptions {
  /** Extra solids beyond the apparatus — the hero tree's existing trunk collider. */
  readonly extraSolids?: readonly CommonGroundAabb[];
  readonly rangeUnits?: number;
}

export interface ReferenceCheck {
  readonly ok: boolean;
  readonly distance: number;
  readonly reason: CommonGroundHoldReason | null;
  readonly blockedBy: string | null;
}

/**
 * One reference relation: socket to socket, in range, with a clear solid
 * segment. Camera direction, reticle, gaze duration, screen visibility and music
 * phase are NOT inputs and never will be — this function cannot see them.
 */
export function checkReference(
  socket: CommonGroundPoint,
  sample: CommonGroundPoint,
  options: ReferenceCheckOptions = {}
): ReferenceCheck {
  const distance = distanceBetween(socket, sample);
  const range = options.rangeUnits ?? REFERENCE_RANGE_UNITS;
  if (distance > range) {
    return { ok: false, distance, reason: 'reference-out-of-range', blockedBy: null };
  }
  for (const box of CG_APPARATUS_SOLIDS) {
    if (!referenceSegmentBlockedBy(socket, sample, box)) continue;
    return {
      ok: false,
      distance,
      reason: 'reference-occluded-survey-housing',
      blockedBy: box.name
    };
  }
  for (const box of options.extraSolids ?? []) {
    if (!referenceSegmentBlockedBy(socket, sample, box)) continue;
    return { ok: false, distance, reason: 'reference-occluded-other-solid', blockedBy: box.name };
  }
  return { ok: true, distance, reason: null, blockedBy: null };
}

// --- Footing -------------------------------------------------------------------------

export interface CommonGroundFooting {
  /** Dry, solid, fully supporting the body disc at this grounded pose. */
  isSupported(point: CommonGroundPoint): boolean;
  /** Opaque token; a change means the terrain moved and routes must revalidate. */
  readonly revision: string;
}

/** Body extents, as qualified. The player is tall; W-7744 is not. */
export const PLAYER_BODY_HEIGHT = 3.6;
export const WORKER_BODY_HEIGHT = 2.01;
export const BODY_RADIUS = 0.5;

export interface WalkedSegmentOptions {
  denseSpacing?: number;
  extraSolids?: readonly CommonGroundAabb[];
  /** Standing height of the body being swept. Defaults to the player's. */
  bodyHeight?: number;
  bodyRadius?: number;
}

function bodyOverlapsBox(
  point: CommonGroundPoint,
  radius: number,
  height: number,
  box: CommonGroundAabb
): boolean {
  return point.x + radius > box.lo.x && point.x - radius < box.hi.x
    && point.z + radius > box.lo.z && point.z - radius < box.hi.z
    && point.y + height > box.lo.y && point.y < box.hi.y;
}

/**
 * A walked segment is supported only if the BODY can actually walk it.
 *
 * The foot-point line is not the query, and the difference is not academic: the
 * apparatus backing starts at y=51.35 and the ground is at 51.05, so a grounded
 * centre line passes cleanly UNDER a slab an upright body walks straight into.
 * Sweeping the body's own extent is what makes the walk mask agree with what the
 * player can see. The fixture boxes are unchanged — checking a body's extent is
 * not the same thing as quietly enlarging a solid into a hidden wall.
 *
 * Dense sampling at 0.25 against a 0.5 radius also means nothing tunnels: a
 * point-only test is exactly what would let a route shortcut a corner or slip
 * through a gap it never fits through.
 */
export function walkedSegmentSupported(
  from: CommonGroundPoint,
  to: CommonGroundPoint,
  footing: CommonGroundFooting,
  options: WalkedSegmentOptions = {}
): boolean {
  const spacing = options.denseSpacing ?? 0.25;
  const radius = options.bodyRadius ?? BODY_RADIUS;
  const height = options.bodyHeight ?? PLAYER_BODY_HEIGHT;
  const length = distanceBetween(from, to);
  const steps = length <= 0 ? 0 : Math.max(1, Math.ceil(length / spacing));
  for (let index = 0; index <= steps; index += 1) {
    const t = steps === 0 ? 0 : index / steps;
    const point = {
      x: from.x + (to.x - from.x) * t,
      y: from.y + (to.y - from.y) * t,
      z: from.z + (to.z - from.z) * t
    };
    if (!footing.isSupported(point)) return false;
    for (const box of CG_APPARATUS_SOLIDS) {
      if (bodyOverlapsBox(point, radius, height, box)) return false;
    }
    for (const box of options.extraSolids ?? []) {
      if (bodyOverlapsBox(point, radius, height, box)) return false;
    }
  }
  return true;
}

/** Whole-route footing validity, reported at the first bad segment. */
export function firstUnsupportedSegment(
  points: readonly CommonGroundPoint[],
  footing: CommonGroundFooting,
  options: WalkedSegmentOptions = {}
): number {
  for (let index = 1; index < points.length; index += 1) {
    if (!walkedSegmentSupported(points[index - 1], points[index], footing, options)) return index;
  }
  return -1;
}

// --- Test progression ----------------------------------------------------------------

export interface SpanTestSource {
  /** The fixed apparatus socket is always available. */
  readonly fixed: CommonGroundPoint;
  /** An occupied, offered reference socket, or null when nobody is holding one. */
  readonly held: CommonGroundPoint | null;
  /**
   * False when the fixed apparatus reference is NOT an available source.
   *
   * His final independent test is witnessed from the separate far Terra socket
   * and from nowhere else: letting the fixed plate quietly cover part of it
   * would mean her offer was decoration for the stretch the apparatus already
   * reaches, which is the opposite of the thing being proved.
   */
  readonly useFixed?: boolean;
  /**
   * The socket height of the body actually walking the span.
   *
   * REFERENCES ARE SOCKET TO SOCKET. Measuring to the ground under a walker's
   * feet would put every ray below the apparatus cap's top face and make the
   * instrument occlude itself from its own reference plane; the qualification
   * pins the cap below every ray socket precisely so endpoint contact stays
   * harmless. Defaults to W-7744's visor, the body that tests offered spans.
   */
  readonly travellerSocketHeight?: number;
}

export interface SpanTestResult {
  /** How many leading samples are actually demonstrable right now. */
  readonly supportedPrefix: number;
  /** Null when the whole offered span is supported. */
  readonly reason: CommonGroundHoldReason | null;
  readonly blockedBy: string | null;
  /** Index of the first sample that could not be supported, or -1. */
  readonly firstUnsupportedIndex: number;
}

/**
 * Walk the offered span and stop at the first sample no available reference can
 * hold, reporting the literal cause.
 *
 * Footing is checked FIRST and separately: an unsafe step is reported as
 * `footing-invalid` and is not reconsidered under a held reference, because a
 * witness cannot make bad ground safe.
 */
export function evaluateOfferedSpan(
  samples: readonly CommonGroundPoint[],
  source: SpanTestSource,
  footing: CommonGroundFooting,
  options: ReferenceCheckOptions & WalkedSegmentOptions = {}
): SpanTestResult {
  if (samples.length === 0) {
    return { supportedPrefix: 0, reason: 'footing-invalid', blockedBy: null, firstUnsupportedIndex: 0 };
  }
  const socketHeight = source.travellerSocketHeight ?? WORKER_REFERENCE_SOCKET_HEIGHT;
  for (let index = 0; index < samples.length; index += 1) {
    if (index > 0 && !walkedSegmentSupported(samples[index - 1], samples[index], footing, options)) {
      return {
        supportedPrefix: index,
        reason: 'footing-invalid',
        blockedBy: null,
        firstUnsupportedIndex: index
      };
    }
    const travelling: CommonGroundPoint = {
      x: samples[index].x,
      y: samples[index].y + socketHeight,
      z: samples[index].z
    };
    const useFixed = source.useFixed !== false;
    const fixed = useFixed
      ? checkReference(source.fixed, travelling, options)
      : null;
    if (fixed?.ok) continue;
    const held = source.held ? checkReference(source.held, travelling, options) : null;
    if (held?.ok) continue;
    const failure = fixed ?? held;
    return {
      supportedPrefix: index,
      reason: failure?.reason ?? 'reference-vacant',
      blockedBy: failure?.blockedBy ?? null,
      firstUnsupportedIndex: index
    };
  }
  return {
    supportedPrefix: samples.length,
    reason: null,
    blockedBy: null,
    firstUnsupportedIndex: -1
  };
}

// --- Occupancy hysteresis ------------------------------------------------------------

function withinCylinder(
  body: CommonGroundPoint,
  pose: CommonGroundPoint,
  radius: number,
  vertical: number
): boolean {
  return Math.hypot(body.x - pose.x, body.z - pose.z) <= radius
    && Math.abs(body.y - pose.y) <= vertical;
}

export function withinOccupancyCylinder(body: CommonGroundPoint, pose: CommonGroundPoint): boolean {
  return withinCylinder(body, pose, OCCUPANCY_RADIUS_UNITS, OCCUPANCY_VERTICAL_UNITS);
}

export function withinReleaseCylinder(body: CommonGroundPoint, pose: CommonGroundPoint): boolean {
  return withinCylinder(body, pose, RELEASE_RADIUS_UNITS, RELEASE_VERTICAL_UNITS);
}

/**
 * Occupancy with hysteresis: entering the inner cylinder establishes it, and
 * only leaving the OUTER one drops it. Turning on the spot, or drifting a few
 * centimetres, cannot flicker a held reference.
 */
export function nextOccupancy(
  occupied: boolean,
  body: CommonGroundPoint,
  pose: CommonGroundPoint
): boolean {
  return occupied ? withinReleaseCylinder(body, pose) : withinOccupancyCylinder(body, pose);
}

/** Two bodies may not stand on top of each other; the reference is a place. */
export function bodiesClear(a: CommonGroundPoint, b: CommonGroundPoint): boolean {
  return Math.hypot(a.x - b.x, a.z - b.z) >= BODY_BODY_CLEARANCE_UNITS;
}

/**
 * Progress along a fixed authored polyline, in walked units.
 *
 * Endpoint proximity is NOT progress. A body must actually traverse the span,
 * so progress advances only while the body is near the segment it claims to be
 * walking, and never jumps ahead of the segment it has reached.
 *
 * THE FRONTIER RULE IS DELIBERATE for a corner that was CUT, and the recorded
 * manual-corner risk (`producer-manual-corner-risk.json`) is its cost there, not
 * a defect in it. `commonGroundRoute.test.ts` reproduces that risk from real
 * per-frame displacement: turning 0.18 units BEFORE a vertex — so that its
 * incoming plane is never actually crossed at the corner — leaves every later
 * projection permanently beyond `previousUnits + displacement`, so the credited
 * span holds at the last ground actually covered (four units, at the corner it
 * failed to round) while
 * the body walks the remaining fourteen units, and three hundred further units
 * of walking on and looping at the far end recover nothing at all.
 *
 * The same tests show that is a LOCK ONLY IF THE BODY NEVER GOES BACK. Walking
 * back along the route to the frontier it actually reached and re-traversing
 * from there credits the full eighteen units exactly — ordinary movement, no
 * reset, no second F, no new marker, and the units earned before the deviation
 * are retained throughout.
 *
 * The cheaper reconciliation — letting the frontier creep toward the body's own
 * projection at walking pace — was implemented, measured and REMOVED: it pays
 * for the omitted wedge with displacement spent anywhere in the corridor,
 * including a wiggle at the far end, which the chapter's signed reading of
 * `#/story/events/21` and `#/guidance/objectives/13` forbids.
 *
 * WHAT THIS RULE IS NOT. It is not a claim that every projection ahead of one
 * frame's displacement is a cut corner. A body that walks THROUGH a vertex and
 * overshoots it — the ordinary way a human rounds a corner — turns onto the next
 * leg already a little way along it, and this function's ceiling then rejects
 * that whole projection frame after frame, because from there the projection and
 * the ceiling advance at the same rate. Measured live: credit 6, projection
 * 6.2944830004, ceiling 6.1635971455, frozen
 * (`producer-common-entry-crossing-review.json`, call 298). That case is settled
 * by `nextRouteCoverage` below, from actual ordered coverage between two real
 * feet, and NOT by loosening anything here: this function is unchanged, and the
 * early cut it refuses stays refused there too.
 */
export function routeProgressUnits(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  previousUnits: number,
  displacementUnits: number,
  corridorRadius = 2.5
): number {
  // NO DISPLACEMENT, NO PROGRESS. A stationary body earns nothing, however long
  // it stands there and however many times it is sampled, which is what makes
  // standing at C worth zero and a timer worth nothing at all.
  if (!(displacementUnits > 0)) return previousUnits;
  // The ceiling is computed ONCE from the progress already earned, so repeated
  // iterations of the scan below cannot compound an allowance, and a later
  // segment's proximity cannot be claimed ahead of the frontier.
  const ceiling = previousUnits + displacementUnits;
  let travelled = 0;
  let best = previousUnits;
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1];
    const to = route[index];
    const segment = distanceBetween(from, to);
    if (segment <= 0) continue;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dz = to.z - from.z;
    const t = Math.max(0, Math.min(1,
      ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
        / (segment * segment)));
    const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
    const arc = travelled + segment * t;
    if (arc > best && arc <= ceiling && distanceBetween(body, closest) <= corridorRadius) {
      best = arc;
    }
    travelled += segment;
  }
  return Math.min(best, travelled);
}

// --- Ordered physical coverage --------------------------------------------------------
//
// ONE defect, one correction, and it is NOT a bank. The frontier rule credited a
// frame only when the body's whole projection fell under `previousUnits +
// displacement`, so an ordinary rounded corner — walk through the vertex,
// overshoot it, turn onto the next leg already a little way along — left a
// residual that no later frame could ever clear, because from then on both the
// projection and the ceiling advanced at exactly the same rate. Measured live
// (`producer-common-entry-crossing-review.json`, call 298 of
// `verifier/captures/common-entry-crossing/run1`): credit exactly 6 at vertex
// (-44, 51.05, 16), foot 0.2742 past it, projection 6.2944830004 against a
// ceiling of 6.1635971455, frozen from there on.
//
// The correction is to measure what the body PHYSICALLY COVERED, in order, from
// its real previous foot to its real current foot, rather than to hand it an
// allowance it may spend anywhere:
//
//   * A vertex is REACHED only by an actual motion that crosses its incoming
//     plane — previous foot strictly short of it, current foot at or past it —
//     AND that passes within the unchanged 0.35 vertex reach of the vertex
//     itself. Both facts come from the two real feet. Standing on the far side
//     proves nothing; being the nearest vertex proves nothing.
//   * Vertices are reached STRICTLY IN ORDER, one route index at a time. A body
//     that cut a corner has not reached it, so nothing beyond it can be covered
//     however far or long it walks afterwards, and the z 15.82 refusal and its
//     walk-back-and-re-traverse repair are exactly preserved.
//   * Within the leg it has actually reached, credit is the body's own position
//     on that leg, clamped to the leg and to the corridor, and monotone. It is
//     the ground under the body, so it cannot be pumped: a stationary, lateral,
//     late-leg or far-end body projects to the same arc however long it wiggles,
//     and nothing at all can be earned past the next unreached vertex.
//   * A motion is only usable while the chain of real feet is unbroken. An
//     unsupported, unreferenced, reset, respawned or freshly seeded frame drops
//     the previous foot, and a null previous foot is never replaced by the
//     current one — a gap is a gap, and no crossing may be claimed across it.
//
// Nothing is granted, no timer, tolerance, corridor, vertex, C or arrival rule
// changes here, and `routeProgressUnits` above is untouched.

/** Unchanged route-vertex reach: how close the body must pass to round a vertex. */
const ROUTE_VERTEX_REACH_UNITS = 0.35;

/**
 * Live, non-persisted physical coverage of the common route.
 *
 * `units` mirrors the credited span, `reachedVertex` is the last route vertex
 * the body actually crossed and passed, and `foot` is its real last position.
 * None of it is stored, restored or trusted across a break: see
 * `syncedRouteCoverage`.
 */
export interface RouteCoverage {
  readonly units: number;
  readonly reachedVertex: number;
  readonly foot: CommonGroundPoint | null;
}

export const NO_ROUTE_COVERAGE: RouteCoverage = Object.freeze({
  units: 0,
  reachedVertex: 0,
  foot: null
});

/** Arc length from the head of the route to `index`. */
function arcAtVertex(route: readonly CommonGroundPoint[], index: number): number {
  let arc = 0;
  for (let i = 1; i <= index && i < route.length; i += 1) {
    arc += distanceBetween(route[i - 1], route[i]);
  }
  return arc;
}

/**
 * The last vertex a span of `units` PROVES was rounded.
 *
 * Strictly below the credit, deliberately. Credit sitting exactly on a vertex's
 * arc does not prove that vertex was passed — the recorded early cut pins at
 * exactly 4 without ever coming within 0.35 of (-42, ., 16) — so a span that has
 * to be re-derived, rather than carried live, always re-derives the conservative
 * answer and makes the body cross the corner again.
 */
function provenVertex(route: readonly CommonGroundPoint[], units: number): number {
  let proven = 0;
  let arc = 0;
  for (let index = 1; index < route.length; index += 1) {
    arc += distanceBetween(route[index - 1], route[index]);
    if (arc + 1e-9 < units) proven = index;
  }
  return proven;
}

/**
 * Coverage re-seeded against the authoritative credited span.
 *
 * The snapshot owns the units. Whenever they differ from what this state last
 * saw — a resumed leg, a migrated save, a rewritten span, an actor or world
 * swap — the reached vertex is re-derived conservatively and the foot chain is
 * dropped, so nothing earned elsewhere is inherited as permission to move on.
 */
export function syncedRouteCoverage(
  route: readonly CommonGroundPoint[],
  coverage: RouteCoverage,
  units: number
): RouteCoverage {
  if (Math.abs(coverage.units - units) <= 1e-9) return coverage;
  return { units, reachedVertex: provenVertex(route, units), foot: null };
}

/** Signed distance along the incoming leg, measured from `route[index]`. */
function planeOffset(
  route: readonly CommonGroundPoint[],
  index: number,
  body: CommonGroundPoint
): number {
  const from = route[index - 1];
  const at = route[index];
  const length = distanceBetween(from, at);
  if (!(length > 0)) return 0;
  return ((body.x - at.x) * (at.x - from.x)
    + (body.y - at.y) * (at.y - from.y)
    + (body.z - at.z) * (at.z - from.z)) / length;
}

/** Closest approach of the real motion `from`->`to` to `point`. */
function segmentApproach(
  from: CommonGroundPoint,
  to: CommonGroundPoint,
  point: CommonGroundPoint
): number {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const dz = to.z - from.z;
  const lengthSq = dx * dx + dy * dy + dz * dz;
  if (!(lengthSq > 0)) return distanceBetween(from, point);
  const t = Math.max(0, Math.min(1,
    ((point.x - from.x) * dx + (point.y - from.y) * dy + (point.z - from.z) * dz) / lengthSq));
  return distanceBetween(point, {
    x: from.x + dx * t,
    y: from.y + dy * t,
    z: from.z + dz * t
  });
}

/**
 * Position on the leg out of `reachedVertex`, or null when the body is not on it.
 *
 * The arc can never leave that leg: the far vertex bounds it until an actual
 * crossing reaches it, which is why no amount of movement beyond an unreached
 * corner is worth anything.
 */
function coveredOnReachedLeg(
  route: readonly CommonGroundPoint[],
  reachedVertex: number,
  body: CommonGroundPoint,
  corridorRadius: number
): number | null {
  const next = reachedVertex + 1;
  if (next >= route.length) return arcAtVertex(route, reachedVertex);
  const from = route[reachedVertex];
  const to = route[next];
  const segment = distanceBetween(from, to);
  if (!(segment > 0)) return null;
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const dz = to.z - from.z;
  const t = Math.max(0, Math.min(1,
    ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
      / (segment * segment)));
  const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
  if (distanceBetween(body, closest) > corridorRadius) return null;
  return arcAtVertex(route, reachedVertex) + segment * t;
}

/**
 * Next credited span, from the body's ACTUAL motion over the route.
 *
 * `coverage.foot` is the real previous foot and is never synthesised from the
 * current one. With no previous foot the motion is unknown, so this update
 * records the foot and credits nothing at all.
 */
export function nextRouteCoverage(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  displacementUnits: number,
  coverage: RouteCoverage,
  corridorRadius = 2.5,
  vertexReach = ROUTE_VERTEX_REACH_UNITS
): RouteCoverage {
  const foot = { x: body.x, y: body.y, z: body.z };
  const previous = coverage.foot;
  // NO MOTION, NO COVERAGE, and no chain either: a body that has not moved has
  // covered nothing, however long it stands there and however often it is
  // sampled. Standing at C is still worth exactly zero.
  if (!previous || !(displacementUnits > 0)) {
    return { units: coverage.units, reachedVertex: coverage.reachedVertex, foot };
  }

  // ONE VERTEX AT A TIME, IN ORDER, each by an actual crossing of its incoming
  // plane made by this very motion, each within the unchanged vertex reach, AND
  // each with the incoming leg ACTUALLY COVERED up to that vertex under the same
  // strict frontier accounting. Crossing a corner is not a receipt for the leg
  // that led to it: a body that was dropped onto the last metre of the leg, or
  // that carries a saved half unit from somewhere else entirely, crosses the
  // plane just as convincingly as one that walked, so the crossing is refused
  // here and the corner is simply not certified.
  let reachedVertex = coverage.reachedVertex;
  let certifiedUnits = coverage.units;
  let certifiedCorner = false;
  while (reachedVertex + 1 < route.length) {
    const next = reachedVertex + 1;
    const crossed = planeOffset(route, next, previous) < 0
      && planeOffset(route, next, foot) >= 0;
    if (!crossed) break;
    if (segmentApproach(previous, foot, route[next]) > vertexReach) break;
    const incomingArc = arcAtVertex(route, next);
    if (certifiedUnits + displacementUnits + 1e-9 < incomingArc) break;
    reachedVertex = next;
    certifiedUnits = Math.max(certifiedUnits, incomingArc);
    certifiedCorner = true;
  }

  // ORDINARY LEG MOVEMENT STAYS STRICT. The body's projection on the leg is only
  // credited when the frontier could honestly have advanced that far in this one
  // update; an arbitrary later projection neither maxes nor creeps toward the
  // frontier, which is what keeps a seeded foot at (-42, ., 13) worth 0 until the
  // start of the leg is physically returned to and re-traversed.
  //
  // The ONE exception is the corner just certified above, where the incoming leg
  // was covered to the vertex and the vertex was really rounded: there the
  // outgoing projection settles the LOCAL residual that corner-cutting geometry
  // creates (call 298: credit 6 at (-44, 51.05, 16), projection 6.2944830004
  // against a per-update ceiling of 6.1635971455). It is bounded by the next
  // unreached vertex, and the very next ordinary update is strict again.
  const onLeg = coveredOnReachedLeg(route, reachedVertex, foot, corridorRadius);
  let covered = certifiedUnits;
  if (onLeg !== null && onLeg > covered
    && (certifiedCorner || onLeg <= coverage.units + displacementUnits + 1e-9)) {
    covered = onLeg;
  }
  return { units: covered, reachedVertex, foot };
}

// --- Display grammar ------------------------------------------------------------------
//
// PURE PLACEMENT MATH, no THREE and no mesh. The renderer turns each placement
// into one instance matrix in the existing pooled unit-box mesh, so the shape a
// player reads is decided here and can be asserted without a GPU.
//
// The signed grammar (`scene-cinema-lane.json#/trace/glyphRealization`) is a
// SHAPE grammar, deliberately, because colour and glow are unavailable evidence:
// they are gone on the lowest tier, gone under a colour-blind profile, and gone
// in a muted, unlit night frame. So:
//
//   proposed sample  -> ONE short bar along the recorded local segment. The gaps
//                       between successive bars are what make it read broken.
//   tested sample    -> TWO parallel bars with a visible gap between them.
//   held endpoint    -> the endpoint's PAIR is REPLACED by two transverse
//                       half-bars with an open centre. Never a third glyph.
//   common guide     -> one thin continuous bar per existing polyline segment.
//
// Two instances per sample is the hard ceiling, and it is what makes 2 x 128
// recorded samples fit the existing 512-instance pool exactly.

/** A single instance of the shared unit-box trace geometry, in world space. */
export interface TraceGlyph {
  /** Centre of the box. `y` already includes the surface offset. */
  readonly x: number;
  readonly y: number;
  readonly z: number;
  /** Rotation about +Y, radians. 0 points along +X. */
  readonly angle: number;
  /** Extent along the bar's own axis. */
  readonly lengthUnits: number;
  /** Extent across the bar. */
  readonly widthUnits: number;
}

/** Sits on the ground rather than in it; the same offset the first pass used. */
export const TRACE_SURFACE_OFFSET = 0.06;
export const TRACE_GLYPH_THICKNESS = 0.06;
/** A proposed/tested bar is short: it marks a place, it does not connect places. */
export const TRACE_BAR_MIN_LENGTH = 0.2;
export const TRACE_BAR_MAX_LENGTH = 0.7;
export const TRACE_BAR_WIDTH = 0.09;
/** The paired stroke's two rails and the gap that makes them read as two. */
export const TRACE_PAIR_WIDTH = 0.07;
export const TRACE_PAIR_SEPARATION = 0.22;
/** The open transverse stop: a bar ACROSS the path, split around an open centre. */
export const TRACE_STOP_SPAN = 0.62;
export const TRACE_STOP_OPENING = 0.2;
/** The planned common guide is a thin continuous line, not a row of marks. */
export const COMMON_GUIDE_WIDTH = 0.05;
/** Sample positions used by the completed paired common display. */
export const COMMON_TESTED_SAMPLE_COUNT = 31;

function normalizeXZ(dx: number, dz: number): { x: number; z: number } | null {
  const length = Math.hypot(dx, dz);
  if (!(length > 1e-6)) return null;
  return { x: dx / length, z: dz / length };
}

/**
 * The direction a mark at `index` is aligned to.
 *
 * At a corner this is the BISECTOR of the actual recorded incoming and outgoing
 * segments, which is what "orient bars from actual recorded incoming/outgoing
 * segments" means for a mark that has two of them. It is never an axis-aligned
 * default, and never an enlarged square standing in for a turn.
 */
function localTangent(
  points: readonly CommonGroundPoint[],
  index: number
): { x: number; z: number } {
  const previous = index > 0 ? points[index - 1] : null;
  const next = index + 1 < points.length ? points[index + 1] : null;
  const here = points[index];
  const incoming = previous ? normalizeXZ(here.x - previous.x, here.z - previous.z) : null;
  const outgoing = next ? normalizeXZ(next.x - here.x, next.z - here.z) : null;
  if (incoming && outgoing) {
    const bisector = normalizeXZ(incoming.x + outgoing.x, incoming.z + outgoing.z);
    // A perfect reversal has no bisector; keep the incoming heading rather than
    // inventing one.
    return bisector ?? incoming;
  }
  return incoming ?? outgoing ?? { x: 1, z: 0 };
}

/** Clamped to the REAL local spacing, so a dense corner cannot draw over itself. */
function localBarLength(points: readonly CommonGroundPoint[], index: number): number {
  let spacing = Infinity;
  if (index > 0) spacing = Math.min(spacing, distanceBetween(points[index - 1], points[index]));
  if (index + 1 < points.length) {
    spacing = Math.min(spacing, distanceBetween(points[index], points[index + 1]));
  }
  if (!Number.isFinite(spacing)) spacing = TRACE_BAR_MAX_LENGTH;
  return Math.max(TRACE_BAR_MIN_LENGTH, Math.min(TRACE_BAR_MAX_LENGTH, spacing * 0.55));
}

function angleOf(direction: { x: number; z: number }): number {
  return Math.atan2(direction.z, direction.x);
}

export interface TraceGlyphOptions {
  /** Leading samples an ACTUAL test has proven. Those read as paired strokes. */
  readonly testedPrefixCount?: number;
  /** Sample index where a real hold stopped the test, or -1/null for none. */
  readonly heldIndex?: number | null;
}

/**
 * Lay out one recorded survey route.
 *
 * Every recorded sample is represented — nothing is decimated to fit, because a
 * dropped interior sample would silently change the argument she walked. The
 * caller is responsible for the pool ceiling; capacity already stopped honestly
 * upstream, in the slot itself.
 */
export function traceGlyphs(
  points: readonly CommonGroundPoint[],
  options: TraceGlyphOptions = {}
): TraceGlyph[] {
  const glyphs: TraceGlyph[] = [];
  const tested = Math.max(0, Math.min(options.testedPrefixCount ?? 0, points.length));
  const held = options.heldIndex ?? -1;
  for (let index = 0; index < points.length; index += 1) {
    const point = points[index];
    const y = point.y + TRACE_SURFACE_OFFSET;
    const tangent = localTangent(points, index);
    const angle = angleOf(tangent);
    if (index === held && held >= 0) {
      // THE OPEN TRANSVERSE STOP REPLACES THE PAIR. The endpoint where his test
      // actually stopped reads as a barrier across the path with its middle
      // left open — the shape of "this is as far as this went", not a decorated
      // version of the mark before it.
      const half = Math.max(0.08, (TRACE_STOP_SPAN - TRACE_STOP_OPENING) / 2);
      const offset = TRACE_STOP_OPENING / 2 + half / 2;
      const across = { x: -tangent.z, z: tangent.x };
      const acrossAngle = angleOf(across);
      for (const sign of [-1, 1]) {
        glyphs.push({
          x: point.x + across.x * offset * sign,
          y,
          z: point.z + across.z * offset * sign,
          angle: acrossAngle,
          lengthUnits: half,
          widthUnits: TRACE_BAR_WIDTH
        });
      }
      continue;
    }
    const length = localBarLength(points, index);
    if (index < tested) {
      const normal = { x: -tangent.z, z: tangent.x };
      const offset = TRACE_PAIR_SEPARATION / 2;
      for (const sign of [-1, 1]) {
        glyphs.push({
          x: point.x + normal.x * offset * sign,
          y,
          z: point.z + normal.z * offset * sign,
          angle,
          lengthUnits: length,
          widthUnits: TRACE_PAIR_WIDTH
        });
      }
      continue;
    }
    glyphs.push({ x: point.x, y, z: point.z, angle, lengthUnits: length, widthUnits: TRACE_BAR_WIDTH });
  }
  return glyphs;
}

/**
 * The planned, unverified common guide over the EXISTING E-to-C polyline.
 *
 * No search, no new route and no stored samples: the vertices are the qualified
 * ones. `supportedThrough` is the last vertex index the live ground actually
 * carries; beyond it the line simply stops, with the same open transverse stop
 * the walked grammar uses, rather than floating over an edited hole or
 * replanning itself around one. A truncated guide changes no state and grants no
 * proof — the existing hold and repair still own that.
 */
export function commonGuideGlyphs(
  route: readonly CommonGroundPoint[],
  supportedThrough: number = route.length - 1
): TraceGlyph[] {
  const glyphs: TraceGlyph[] = [];
  const last = Math.max(0, Math.min(supportedThrough, route.length - 1));
  for (let index = 1; index <= last; index += 1) {
    const from = route[index - 1];
    const to = route[index];
    const direction = normalizeXZ(to.x - from.x, to.z - from.z);
    const length = distanceBetween(from, to);
    if (!direction || !(length > 0)) continue;
    glyphs.push({
      x: (from.x + to.x) / 2,
      y: (from.y + to.y) / 2 + TRACE_SURFACE_OFFSET,
      z: (from.z + to.z) / 2,
      angle: angleOf(direction),
      lengthUnits: length,
      widthUnits: COMMON_GUIDE_WIDTH
    });
  }
  if (last < route.length - 1) {
    const point = route[last];
    const tangent = localTangent(route, last);
    const across = { x: -tangent.z, z: tangent.x };
    const half = Math.max(0.08, (TRACE_STOP_SPAN - TRACE_STOP_OPENING) / 2);
    const offset = TRACE_STOP_OPENING / 2 + half / 2;
    const acrossAngle = angleOf(across);
    for (const sign of [-1, 1]) {
      glyphs.push({
        x: point.x + across.x * offset * sign,
        y: point.y + TRACE_SURFACE_OFFSET,
